//! `sermofur_mcp::codex_config` against `CodexConfigFile` of the oracle
//! (`rust/tests/golden/codex-config.json`, regenerated by `rust/tools/codex-config-oracle`):
//! every case, for every launch command, character for character, refusals included. The facts
//! of `CodexConfigFileTests` are unit tests of the module; its two properties are here (lot 8.2).
//! Lives in `smf` because `sermofur-mcp` has no JSON or proptest dependency.

use std::path::Path;

use serde_json::{Value, json};
use sermofur_core::error::SermofurError;
use sermofur_mcp::codex_config::{declares, with_block, without_block};

fn outcome<T>(result: Result<T, SermofurError>, as_json: impl Fn(T) -> Value) -> Value {
    match result {
        Ok(value) => as_json(value),
        Err(error) => {
            json!({"code": error.code, "message": error.message, "exit": error.exit_code})
        }
    }
}

fn text(value: Option<String>) -> Value {
    value.map_or(json!({"null": true}), |text| json!({"text": text}))
}

#[test]
fn codex_config_matches_the_oracle() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/codex-config.json");
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden")).expect("JSON");
    let entries: Vec<(String, Vec<String>)> = golden["entries"]
        .as_array()
        .expect("entries")
        .iter()
        .map(|e| {
            let args = e["args"].as_array().expect("args").iter();
            (
                e["command"].as_str().expect("command").to_owned(),
                args.map(|a| a.as_str().expect("arg").to_owned()).collect(),
            )
        })
        .collect();
    let mut mismatches = Vec::new();
    for (index, (command, args)) in entries.iter().enumerate() {
        let actual = outcome(with_block(None, command, args), text);
        if actual != golden["absent"][index] {
            mismatches.push(format!(
                "absent #{index}: {actual} != {}",
                golden["absent"][index]
            ));
        }
    }
    let cases = golden["cases"].as_array().expect("cases");
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let content = case["content"].as_str().expect("content");
        for (index, (command, args)) in entries.iter().enumerate() {
            let actual = outcome(with_block(Some(content), command, args), text);
            if actual != case["withBlock"][index] {
                mismatches.push(format!(
                    "{name} withBlock #{index}: {actual} != {}",
                    case["withBlock"][index]
                ));
            }
        }
        let actual = outcome(without_block(content), text);
        if actual != case["withoutBlock"] {
            mismatches.push(format!(
                "{name} withoutBlock: {actual} != {}",
                case["withoutBlock"]
            ));
        }
        let actual = outcome(declares(content), |flag| json!({"declares": flag}));
        if actual != case["declares"] {
            mismatches.push(format!("{name} declares: {actual} != {}", case["declares"]));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
    assert!(cases.len() >= 130, "the golden file lost cases");
}

mod properties {
    use proptest::prelude::*;
    use sermofur_mcp::codex_config::{with_block, without_block};

    fn serve() -> Vec<String> {
        vec!["mcp".to_owned(), "serve".to_owned()]
    }

    /// `Tables` of `CodexConfigFileTests`, on the cleaned names.
    fn tables(names: &[String], nl: &str, comments: bool) -> String {
        names
            .iter()
            .map(|n| {
                let comment = if comments { format!("# server {n}{nl}") } else { String::new() };
                format!("{comment}[mcp_servers.{n}]{nl}command = '{n}'{nl}[mcp_servers.{n}.env]{nl}K = '{n}'  # kept{nl}{nl}")
            })
            .collect()
    }

    fn clean(names: Vec<String>) -> Vec<String> {
        let mut seen = Vec::new();
        for name in names {
            if name != "sermofur" && !seen.contains(&name) {
                seen.push(name);
            }
        }
        seen
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(300))]

        /// `InstallThenRemoveIsTheIdentity`.
        #[test]
        fn install_then_remove_is_the_identity(
            names in proptest::collection::vec("[a-zA-Z0-9]{1,8}", 0..5),
            crlf in any::<bool>(),
            comments in any::<bool>(),
            final_newline in any::<bool>(),
        ) {
            let nl = if crlf { "\r\n" } else { "\n" };
            let mut content = tables(&clean(names), nl, comments);
            if !final_newline && !content.is_empty() {
                content = content.trim_end_matches(['\r', '\n']).to_owned();
            }
            let expected = if content.is_empty() || content.ends_with('\n') {
                content.clone()
            } else {
                format!("{content}{nl}")
            };
            let installed = with_block(Some(&content), "smf", &serve()).unwrap().unwrap();
            prop_assert_eq!(without_block(&installed).unwrap(), Some(expected));
        }

        /// `RemovalFromTheMiddleKeepsTheRest`.
        #[test]
        fn removal_from_the_middle_keeps_the_rest(
            first in proptest::collection::vec("[a-zA-Z0-9]{1,8}", 0..5),
            second in proptest::collection::vec("[a-zA-Z0-9]{1,8}", 0..5),
            crlf in any::<bool>(),
        ) {
            let nl = if crlf { "\r\n" } else { "\n" };
            let before = tables(&clean(first), nl, true);
            let mut rest = clean(second);
            rest.push("last".to_owned());
            let after = tables(&rest, nl, true);
            let block = format!("[mcp_servers.sermofur]{nl}command = 'smf'{nl}args = ['mcp', 'serve']{nl}{nl}[mcp_servers.sermofur.env]{nl}K = 'v'{nl}{nl}");
            prop_assert_eq!(
                without_block(&format!("{before}{block}{after}")).unwrap(),
                Some(format!("{before}{after}"))
            );
        }

        /// Any text: an answer or a refusal, never a panic. A second install is not always a
        /// no-op (a lone carriage return turns the line ending to CRLF), as with the oracle.
        #[test]
        fn arbitrary_text_never_panics(content in "(?s).{0,200}", wrapped in any::<bool>()) {
            let content = if wrapped { format!("[mcp_servers.sermofur]\n{content}") } else { content };
            let _ = without_block(&content);
            if let Ok(Some(out)) = with_block(Some(&content), "smf", &serve()) {
                prop_assert!(sermofur_mcp::codex_config::declares(&out).is_ok());
            }
        }
    }
}
